import{_ as t,o,c as i,a5 as n}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"Kế hoạch kỹ thuật System Health MongoDB","description":"","frontmatter":{},"headers":[],"relativePath":"feature/modules/07-billing-publisher-and-observability/system-health-mongodb-refactor/plan.md","filePath":"feature/modules/07-billing-publisher-and-observability/system-health-mongodb-refactor/plan.md"}'),c={name:"feature/modules/07-billing-publisher-and-observability/system-health-mongodb-refactor/plan.md"};function r(a,e,l,d,s,h){return o(),i("div",null,[...e[0]||(e[0]=[n('<p>&gt; <strong>Navigation:</strong> <a href="./../README.html">← Category Index</a> · <a href="./../../README.html">← Modules Index</a> · <a href="./spec.html">Spec</a> · <strong>Plan</strong> · <a href="./task.html">Task</a> · <a href="./test.html">Test</a></p><h1 id="ke-hoach-ky-thuat-system-health-mongodb" tabindex="-1">Kế hoạch kỹ thuật System Health MongoDB <a class="header-anchor" href="#ke-hoach-ky-thuat-system-health-mongodb" aria-label="Permalink to &quot;Kế hoạch kỹ thuật System Health MongoDB&quot;">​</a></h1><p>Tham chiếu gốc: <code>tuan-research/system-health-mongodb-refactor/plan.md</code>.</p><h2 id="_1-can-cu-code-va-điem-de-bo-sot" tabindex="-1">1. Căn cứ code và điểm dễ bỏ sót <a class="header-anchor" href="#_1-can-cu-code-va-điem-de-bo-sot" aria-label="Permalink to &quot;1. Căn cứ code và điểm dễ bỏ sót&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Nguồn</th><th>Quan sát và hệ quả</th></tr></thead><tbody><tr><td>brandhub-infrastructure/database/init/init-postgres-v2.sql:1112–1230</td><td>5 bảng, CHECK/FK, latest-only; chuyển Mongo phải thay bảo đảm đang do SQL thực hiện</td></tr><tr><td>brandhub-business-service/.../service/monitoring/HealthIngestionService.java</td><td>JPA lock target, kiểm tra collector, duplicate, ordering; không chỉ đổi annotation</td></tr><tr><td>brandhub-business-service/.../service/monitoring/ServerMonitoringService.java</td><td>Heartbeat dirty-check qua JPA; Mongo cần update tường minh, không replace document</td></tr><tr><td>brandhub-business-service/.../service/monitoring/MonitoringEnrollmentService.java</td><td>JdbcTemplate DELETE RETURNING + INSERT host cùng transaction</td></tr><tr><td>brandhub-business-service/.../service/monitoring/HealthQueryService.java</td><td>Page catalog trước, batch samples/collectors, status filter sau pagination</td></tr><tr><td>brandhub-business-service/.../service/monitoring/MonitoringHealthView.java</td><td>Tính freshness tại thời điểm đọc, không lưu status</td></tr><tr><td>brandhub-business-service/.../service/monitoring/MonitoringAccess.java</td><td>Current ADMIN đọc PostgreSQL; token hash so sánh constant-time</td></tr><tr><td>brandhub-monitoring/src/provision.mjs</td><td>Ghi SQL trực tiếp cả catalog trong một transaction; phải đổi cùng backend</td></tr><tr><td>brandhub-monitoring/src/main.mjs</td><td>Worker runtime gửi HTTP; không cần quyền ghi database catalog</td></tr><tr><td>brandhub-business-service/pom.xml, src/main/resources/application.yml</td><td>Đã có Spring Data MongoDB; cấu hình Mongo hiện hữu</td></tr></tbody></table><h2 id="_2-model-va-collections-mongodb" tabindex="-1">2. Model và Collections MongoDB <a class="header-anchor" href="#_2-model-va-collections-mongodb" aria-label="Permalink to &quot;2. Model và Collections MongoDB&quot;">​</a></h2><p>Dùng 4 collection thông thường trong database Mongo Business:</p><ol><li><p><code>monitoring_servers</code>:</p><ul><li><code>_id</code>: String (canonical UUID lowercase)</li><li><code>name</code>: String</li><li><code>ipAddress</code>: String (chuẩn hóa IPv4/IPv6)</li><li><code>environment</code>: String</li><li><code>deployedServices</code>: Array&lt;String&gt;</li><li><code>agentTokenHash</code>: String</li><li><code>cpuPercent</code>: Decimal128 / Double</li><li><code>ramPercent</code>: Decimal128 / Double</li><li><code>diskPercent</code>: Decimal128 / Double</li><li><code>uptimeSeconds</code>: Long (Int64)</li><li><code>lastSeenAt</code>: Date</li><li><code>createdAt</code>: Date</li><li><code>updatedAt</code>: Date</li></ul></li><li><p><code>monitoring_collectors</code>:</p><ul><li><code>_id</code>: String (UUID)</li><li><code>name</code>: String</li><li><code>serverId</code>: String (UUID)</li><li><code>tokenHash</code>: String</li><li><code>lastSeenAt</code>: Date</li><li><code>createdAt</code>: Date</li><li><code>updatedAt</code>: Date</li></ul></li><li><p><code>monitoring_health_targets</code>:</p><ul><li><code>_id</code>: String (UUID)</li><li><code>name</code>: String</li><li><code>kind</code>: String (SERVICE, CONTAINER, DATABASE, ENDPOINT)</li><li><code>environment</code>: String</li><li><code>serverId</code>: String (UUID)</li><li><code>serviceName</code>: String</li><li><code>instanceId</code>: String</li><li><code>collectorId</code>: String (UUID)</li><li><code>checkScope</code>: String</li><li><code>probeType</code>: String (HTTP, DOCKER, POSTGRESQL, REDIS, MONGODB, NEO4J)</li><li><code>probeConfig</code>: Object</li><li><code>assertion</code>: Object</li><li><code>credentialRef</code>: String</li><li><code>intervalSeconds</code>: Integer</li><li><code>timeoutSeconds</code>: Integer</li><li><code>staleAfterSeconds</code>: Integer</li><li><code>catalogVersion</code>: Long</li><li><code>createdAt</code>: Date</li><li><code>updatedAt</code>: Date</li><li><code>latestResult</code>: Object null hoặc chứa mẫu mới nhất: <ul><li><code>checkId</code>: String (UUID)</li><li><code>collectorId</code>: String (UUID)</li><li><code>outcome</code>: String (PASS, FAIL, ERROR)</li><li><code>checkedAt</code>: Date</li><li><code>checkedAtMicros</code>: Long</li><li><code>receivedAt</code>: Date</li><li><code>latencyMs</code>: Decimal128</li><li><code>reasonCode</code>: String</li><li><code>httpStatus</code>: Integer</li><li><code>runtimeState</code>: String</li><li><code>runtimeHealth</code>: String</li></ul></li></ul></li><li><p><code>monitoring_enrollments</code>:</p><ul><li><code>_id</code>: String (tokenHash hex 64)</li><li><code>name</code>: String</li><li><code>environment</code>: String</li><li><code>expiresAt</code>: Date (TTL index: <code>expireAfterSeconds: 0</code>)</li></ul></li></ol><h2 id="_3-persistence-seam-storage-mode" tabindex="-1">3. Persistence Seam &amp; Storage Mode <a class="header-anchor" href="#_3-persistence-seam-storage-mode" aria-label="Permalink to &quot;3. Persistence Seam &amp; Storage Mode&quot;">​</a></h2><ul><li>Thiết kế persistence seam qua interface <code>MonitoringStore</code> (hoặc các interfaces chuyên trách: <code>ServerMonitoringStore</code>, <code>HealthMonitoringStore</code>, <code>EnrollmentMonitoringStore</code>).</li><li>Implement hai adapter: <ol><li><code>PostgreSqlMonitoringStore</code>: giữ nguyên hành vi JDBC/JPA hiện tại cho fallback/rollback window.</li><li><code>MongoMonitoringStore</code>: sử dụng <code>MongoTemplate</code> cho conditional atomic updates (<code>$set</code>, <code>$unset</code>), transaction cho register, TTL và query projection.</li></ol></li><li>Cấu hình qua thuộc tính <code>monitoring.storage</code>: <code>postgres</code> (mặc định) hoặc <code>mongo</code>.</li><li>Services (<code>ServerMonitoringService</code>, <code>HealthIngestionService</code>, <code>HealthQueryService</code>, <code>MonitoringEnrollmentService</code>) phụ thuộc vào Seam, không trực tiếp thao tác JPA/Jdbc/Mongo.</li></ul><h2 id="_4-concurrency-va-transaction-rules" tabindex="-1">4. Concurrency và Transaction Rules <a class="header-anchor" href="#_4-concurrency-va-transaction-rules" aria-label="Permalink to &quot;4. Concurrency và Transaction Rules&quot;">​</a></h2><ul><li><strong>Heartbeat host/collector</strong>: Conditional <code>$set</code> với <code>_id</code> và <code>tokenHash</code> trong query selector; không dùng upsert, không dùng read-then-save để tránh overwrite metadata/credentials.</li><li><strong>Probe Result Ingestion</strong>: <ul><li>CAS update trên target: match <code>_id</code>, <code>collectorId</code>, <code>catalogVersion</code>, và điều kiện <code>latestResult</code> null HOẶC <code>latestResult.checkedAt</code> &lt; request.checkedAt.</li><li>Phân loại lỗi chính xác: duplicate checkId -&gt; return { duplicate: true }; older timestamp -&gt; 409 CONFLICT; collector mismatch -&gt; 403 FORBIDDEN; not found -&gt; 404 NOT_FOUND.</li></ul></li><li><strong>Enrollment</strong>: <ul><li><code>invite</code>: insert enrollment document với <code>_id=tokenHash</code>, TTL index trên <code>expiresAt</code>.</li><li><code>register</code>: Mongo session transaction: <code>findOneAndDelete</code> enrollment còn hạn (<code>expiresAt &gt; now</code>), <code>insert</code> server host. Nếu insert server lỗi, transaction tự rollback cả hai.</li></ul></li></ul><hr><h2 id="appendix-cutover-runbook" tabindex="-1">Appendix: Cutover Runbook <a class="header-anchor" href="#appendix-cutover-runbook" aria-label="Permalink to &quot;Appendix: Cutover Runbook&quot;">​</a></h2><h3 id="t9-—-cutover-system-health-sang-mongodb" tabindex="-1">T9 — Cutover System Health sang MongoDB <a class="header-anchor" href="#t9-—-cutover-system-health-sang-mongodb" aria-label="Permalink to &quot;T9 — Cutover System Health sang MongoDB&quot;">​</a></h3><p>Trạng thái: chuẩn bị, <strong>chưa thực hiện cutover</strong>. Database production vẫn phải giữ 5 bảng SQL trong rollback window.</p><h2 id="bang-chung-truoc-cutover" tabindex="-1">Bằng chứng trước cutover <a class="header-anchor" href="#bang-chung-truoc-cutover" aria-label="Permalink to &quot;Bằng chứng trước cutover&quot;">​</a></h2><ul><li>Atlas thật, database riêng <code>brandhub_monitoring_acceptance</code>: 5/5 integration test pass, 0 skipped.</li><li>Rehearsal trên PostgreSQL database riêng cùng tên và Atlas acceptance: backfill/verify pass; thêm 2 hosts, thêm collector, consume enrollment, reassign target và ghi sample microsecond; reverse-sync và verify pass, 0 discrepancies.</li><li>Manifest local: <code>tuan-research/system-health-mongodb-refactor/rehearsal-result.json</code>. PostgreSQL test và Atlas test giữ fixture sau rehearsal để kiểm tra, không reset tự động.</li><li>Các revision HEAD hiện tại chưa chứa phần refactor chưa commit: Business <code>0fa2ba2</code>, infrastructure <code>b5f99dd</code>, worker <code>a8f145d</code>. Phải build/deploy đúng working changes đã nghiệm thu, không chỉ redeploy image cũ.</li></ul><h2 id="cau-hinh-release" tabindex="-1">Cấu hình release <a class="header-anchor" href="#cau-hinh-release" aria-label="Permalink to &quot;Cấu hình release&quot;">​</a></h2><p>Compose Business đã có <code>MONITORING_STORAGE: ${MONITORING_STORAGE:-postgres}</code>. Thêm biến vào file .env không tự đổi container đang chạy; cần recreate/deploy cả fleet từ image refactor. Default vẫn postgres để không chuyển traffic trước backfill.</p><p>Database Mongo production lấy từ cấu hình Business <code>MONGODB_DATABASE</code>. Không dùng database acceptance cho cutover. Provision worker dùng cùng database production và Mongo catalog mode. Không cấp quyền catalog-write cho runtime HTTP collector.</p><h2 id="trinh-tu-thuc-hien-trong-cua-so-bao-tri" tabindex="-1">Trình tự thực hiện trong cửa sổ bảo trì <a class="header-anchor" href="#trinh-tu-thuc-hien-trong-cua-so-bao-tri" aria-label="Permalink to &quot;Trình tự thực hiện trong cửa sổ bảo trì&quot;">​</a></h2><ol><li>Khóa release image/commit refactor cho tất cả Business replica và provisioning tool. Xác nhận backup PostgreSQL và Atlas phục hồi được; ghi danh sách replica/writers.</li><li>Freeze tất cả monitoring writers: host heartbeat, collector heartbeat, health-results, invite/register và operator provisioning. Drain requests. API write bị gate phải trả lỗi bảo trì, không nhận rồi bỏ dữ liệu.</li><li>Chạy schema APPLY vào database Mongo production xác nhận rõ tên. Không chạy suite Atlas vì suite xóa dữ liệu test. Nếu collection production đã có dữ liệu khác, dừng và đối chiếu nguồn, không blind overwrite.</li><li>Chạy backfill với PostgreSQL production chỉ đọc và Mongo production ghi, sau đó verify 0 discrepancies. Ghi manifest/count/thời gian. Chỉ thao tác khi writers đã freeze.</li><li>Deploy toàn bộ Business refactor với <code>MONITORING_STORAGE=mongo</code>, giữ các cấu hình PostgreSQL để auth ADMIN vẫn hoạt động. Chuyển operator provisioning cùng đợt. Xác nhận không replica SQL-mode còn nhận request.</li><li>Smoke ADMIN list, host/collector heartbeat, result duplicate/order và enrollment trên đối tượng smoke có danh tính riêng. Mở writers, quan sát ít nhất một chu kỳ host/collector/probe; kiểm UI dữ liệu mới không chỉ snapshot cũ.</li><li>Ghi cutover time, replica/image/config, verify và smoke result. T9 chỉ tick khi có bằng chứng thực thi đủ các bước trên.</li></ol><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Trước khi Mongo có write mới: chuyển toàn fleet về postgres theo gate.</p><p>Sau khi Mongo có write mới: freeze/drain, reverse-export Mongo production sang PostgreSQL trong transaction, verify 0 discrepancies, kiểm host mới/enrollment consumed/owner/result timestamp, rồi chuyển fleet và provisioning về postgres. Không chỉ flip flag vì SQL snapshot đã cũ. Không reverse-sync từ acceptance vào production.</p><h2 id="sau-cutover" tabindex="-1">Sau cutover <a class="header-anchor" href="#sau-cutover" aria-label="Permalink to &quot;Sau cutover&quot;">​</a></h2><p>Theo dõi ít nhất 24 giờ và giữ rollback window đề xuất 7 ngày. Ghi lỗi/p95/throughput và SQL monitoring writes so baseline; không suy giảm tải từ số bảng.</p><p>T11 chỉ thực hiện khi có T9/T10 và hết rollback window: backup cuối, xác nhận không consumer SQL/JPA recreate, gỡ adapter rồi retirement migration có guard, không CASCADE. <strong>Không có lệnh DROP production trong phiên rehearsal này.</strong></p>',29)])])}const m=t(c,[["render",r]]);export{u as __pageData,m as default};
